 function marketView(){const rows=marketData.rows.slice(0,30);return '<div class="u-lead"><div><span class="u-kicker">TRANSFER MARKET / ZF</span><h1>'+t('Znajdź brakujące ogniwo.','Find your missing piece.')+'</h1><p class="u-subtitle">'+t('Karty wystawiają inni gracze. Kupujesz konkretną kartę za widoczną cenę. Swoje oferty możesz zawsze wycofać przed sprzedażą.','Other players list cards here. Buy the exact card at the displayed price. Withdraw your own listings at any time before they sell.')+'</p></div><button data-u="market-refresh">↻ '+t('Odśwież','Refresh')+'</button></div><form id="u-market-filter" class="u-filter-bar"><input id="u-market-search" value="'+esc(marketQuery)+'" placeholder="'+t('Nazwisko piłkarza…','Player name…')+'" aria-label="'+t('Nazwisko piłkarza','Player name')+'"><select id="u-market-position" aria-label="'+t('Pozycja','Position')+'"><option value="">'+t('Wszystkie pozycje','All positions')+'</option>'+['GK','LB','CB','RB','CM','CAM','LW','ST','RW'].map(p=>'<option '+(p===marketPosition?'selected':'')+'>'+p+'</option>').join('')+'</select><button class="u-primary">'+t('Szukaj ofert','Search listings')+'</button></form><div class="u-section-title"><h2>'+t('Oferty graczy','Player listings')+'</h2><small>'+t('Od najniższej ceny','Lowest price first')+'</small></div>'+(rows.length?'<div class="u-collection">'+rows.map(l=>listingTile(l)).join('')+'</div>':'<div class="u-empty"><h2>'+t('Brak ofert dla tych filtrów','No listings match these filters')+'</h2><p>'+t('Wystaw kartę z zakładki Zawodnicy lub sprawdź ponownie później.','List a card from Players or check again later.')+'</p></div>')+'<div class="u-page-controls"><button data-u="market-prev" '+(marketPage===0?'disabled':'')+'>←</button><span>'+t('Strona ','Page ')+(marketPage+1)+'</span><button data-u="market-next" '+(!marketData.has_more?'disabled':'')+'>→</button></div><div class="u-section-title"><h2>'+t('Moje aktywne oferty','My active listings')+'</h2><small>'+marketData.own.length+' / 50</small></div><div class="u-collection">'+marketData.own.map(l=>listingTile(l,true)).join('')+'</div>'+(!marketData.own.length?'<p class="u-subtitle">'+t('Nie masz aktywnych ofert. Wejdź w Zawodnicy → Szczegóły i sprzedaż → Wystaw.','No active listings. Go to Players → Details & sale → List card.')+'</p>':'');}
 function marketBuyModal(id){const l=marketData.rows.find(x=>x.id===id);if(!l||l.own)return;modal='<span class="u-kicker">TRANSFER MARKET</span><h2>'+esc(D.byId[l.player_id].name)+'</h2><p class="u-subtitle">'+t('Kupisz jedną kartę za ','Buy one card for ')+Number(l.price).toLocaleString()+' ZF. '+t('Sprzedawca: ','Seller: ')+esc(l.seller)+'</p><div class="u-modal-actions"><button data-market-confirm="'+esc(id)+'" class="u-primary">'+t('Potwierdź zakup','Confirm purchase')+'</button><button data-u="modal-close">'+t('Anuluj','Cancel')+'</button></div>';drawModal();}
 function trainingView(){return '<div class="u-store-hero u-training-hero"><div><span class="u-kicker">TRAINING GROUND / NO PRESSURE</span><h1>'+t('Wypracuj swój strzał.','Make every shot count.')+'</h1><p class="u-subtitle">'+t('Twój napastnik kontra bramkarz AI. Bez zegara i bez opłat. Ćwicz celowanie, wybierz narożnik i powtarzaj próby klawiszem R.','Your striker against an AI keeper. No clock, no fees. Practice your aim, pick a corner and repeat attempts with R.')+'</p></div><div class="u-training-target" aria-hidden="true"><i></i><b>90</b></div></div><div class="u-training-grid">'+[['open','01',t('Swobodne strzały','Free shooting'),t('Prowadź piłkę, zmieniaj kąt i strzelaj na bramkę bronioną przez bota.','Dribble, change your angle and shoot past the AI keeper.')],['penalty','02',t('Rzuty karne','Penalties'),t('Stały punkt karny. Wybierz stronę strzału i wygraj pojedynek z bramkarzem.','Start at the penalty spot. Pick a side and beat the goalkeeper.')],['free-kick','03',t('Rzuty wolne','Free kicks'),t('Strzały zza pola karnego z murem obrońców i aktywnym bramkarzem.','Shoot from outside the box against a defensive wall and active keeper.')]].map(([id,n,title,desc])=>'<section class="u-panel"><span class="u-kicker">DRILL '+n+'</span><h2>'+title+'</h2><p class="u-subtitle">'+desc+'</p><button data-practice="'+id+'" class="u-primary">'+t('Rozpocznij trening','Start training')+' →</button></section>').join('')+'</div>';}
