 function assign(id){const c=draft.cards.find(c=>c.id===id);if(!c)return;const p=D.byId[c.player_id];if(!D.fits(draft,target,p))return toast(t('Ten piłkarz nie gra na wybranej pozycji.','This player cannot play in the selected position.'));const same=draft.squad.findIndex(cid=>draft.cards.find(c=>c.id===cid)?.player_id===c.player_id);if(same>=0&&same!==target){const outgoing=D.byId[getCard(target)?.player_id];if(!D.fits(draft,same,outgoing))return toast(t('Ta zamiana pozostawiłaby innego piłkarza na złej pozycji. Wybierz kartę z rezerw.','This swap would leave another player out of position. Choose a reserve card.'));[draft.squad[target],draft.squad[same]]=[draft.squad[same],draft.squad[target]];}else draft.squad[target]=id;tab='club';render();}
