 function saveDemo(){club.testPacks={...testPacks};draft=E.copy(club);localStorage.setItem('zone-football-ut-demo',JSON.stringify(club));}
 function demoPack(id,free=true){const pack=D.packs.find(p=>p.id===id);if(!pack)throw Error('FOOTBALL_PACK');if(free&&!(testPacks[id]>0))throw Error('FOOTBALL_TEST_PACKS_EMPTY');if(!free&&club.zf<pack.price)throw Error('FOOTBALL_ZF_FUNDS');const pulled=[];for(let i=0;i<pack.count;i++){const roll=crypto.getRandomValues(new Uint32Array(1))[0]/4294967296*100;let total=0,tier='bronze';for(let n=0;n<4;n++){total+=pack.odds[n];if(roll<total){tier=['bronze','silver','gold','elite'][n];break;}}const pool=D.players.filter(p=>p.tier===tier&&(!pack.positions||pack.positions.includes(p.position))),p=pool[crypto.getRandomValues(new Uint32Array(1))[0]%pool.length];pulled.push({id:'demo-'+crypto.randomUUID(),player_id:p.id});}if(free)testPacks[id]--;else club.zf-=pack.price;club.cards.push(...pulled);saveDemo();return{pulled};}
 async function buyPack(id,free=false){if(busy)return;const key='zone-football-pack-'+((typeof SBU!=='undefined'?SBU?.id:null)||'demo')+'-'+(free?'test-':'paid-')+id;let nonce=sessionStorage.getItem(key);if(!nonce){nonce=crypto.randomUUID();sessionStorage.setItem(key,nonce);}busy=true;node.querySelector('[data-purchase]')?.setAttribute('disabled','');try{const result=!root.zoneFootballDesktop?.club?demoPack(id,free):await rpc(free?'open_test_pack':'buy_pack',{pack:id,nonce,...(!free?{expected_zf:D.packs.find(p=>p.id===id).price}:{})});accept(result);sessionStorage.removeItem(key);modal=root.ZoneFootballPackShow.stage({pack:D.packs.find(p=>p.id===id),players:result.pulled.map(c=>D.byId[c.player_id]),card,free});render();}catch(err){if(/WALLET_FUNDS|FOOTBALL_PACK|OWNERSHIP|TEST_PACKS_EMPTY|ZF_FUNDS|FOOTBALL_PRICE/.test(String(err.message)))sessionStorage.removeItem(key);closeModal();toast(errorText(err));}finally{busy=false;}}
